339	    /// A no-op runner that always reports success for any git command.
340	    struct NoopRunner;
341	
342	    impl CommandRunner for NoopRunner {
343	        fn run(
344	            &self,
345	            _program: &str,
346	            _args: &[&str],
347	            _cwd: &Path,
348	        ) -> Result<CommandOutput, CommandError> {
349	            Ok(CommandOutput {
350	                exit_code: Some(0),
351	                stdout: String::new(),
352	                stderr: String::new(),
353	            })
354	        }
355	    }
356	
357	    type CallLog = std::sync::Arc<std::sync::Mutex<Vec<(String, Vec<String>)>>>;
358	
359	    /// Records every (program, args) pair that CommandRunner::run is called with.
360	    struct RecordingRunner {
361	        #[allow(clippy::type_complexity)]
362	        calls: CallLog,
363	    }
364	
365	    impl CommandRunner for RecordingRunner {
366	        fn run(
367	            &self,
368	            program: &str,
369	            args: &[&str],
370	            _cwd: &Path,
371	        ) -> Result<CommandOutput, CommandError> {
372	            self.calls.lock().unwrap().push((
373	                program.to_string(),
374	                args.iter().map(|s| s.to_string()).collect(),
375	            ));
376	            Ok(CommandOutput {
377	                exit_code: Some(0),
378	                stdout: String::new(),
379	                stderr: String::new(),
380	            })
381	        }
382	    }
383	
384	    fn cargo_version(v: &str) -> Version {
385	        Version::parse(v, VersionGrammar::SemVer).expect("valid semver")
386	    }
