388	    /// When only a Cargo package is bumped, the Python lockfile (`uv.lock`)
389	    /// must NOT appear in `staged`, even when it exists on disk alongside
390	    /// `Cargo.lock`.
391	    #[test]
392	    fn cargo_only_bump_does_not_stage_python_lockfile() {
393	        let dir = tempfile::tempdir().expect("create tempdir");
394	        let root = dir.path();
395	
396	        // Place both a Cargo lockfile and a Python lockfile on disk.
397	        std::fs::write(root.join("Cargo.lock"), "# fake Cargo.lock").unwrap();
398	        std::fs::write(root.join("uv.lock"), "# fake uv.lock").unwrap();
399	
400	        let plan = VersionPlan {
401	            bumps: vec![PlannedBump {
402	                package: PackageId::parse("cargo:my-crate").expect("valid package id"),
403	                from: cargo_version("1.0.0"),
404	                to: cargo_version("1.1.0"),
405	                severity: Severity::Minor,
406	                governed_by: None,
407	                reason: None,
408	                writes: vec![], // no manifest writes — keeps test self-contained
409	            }],
410	            ..Default::default()
411	        };
412	
413	        let permit = ApplyPermit::force_for_tests();
414	        let opts = ApplyOptions::default();
415	        let outcome = apply_version_plan(root, &plan, &NoopRunner, &opts, &permit)
416	            .expect("apply_version_plan should succeed");
417	
418	        let staged_names: Vec<&str> = outcome.staged.iter().filter_map(|p| p.to_str()).collect();
419	
420	        assert!(
421	            staged_names.contains(&"Cargo.lock"),
422	            "Cargo.lock should be staged when a Cargo package is bumped, got: {staged_names:?}"
423	        );
424	        assert!(
425	            !staged_names.contains(&"uv.lock"),
426	            "uv.lock must NOT be staged when no Python package is bumped, got: {staged_names:?}"
427	        );
428	    }
