430	    /// When `refresh_lockfiles: true` and the plan bumps a Cargo package,
431	    /// `cargo update --workspace` must be called so that `Cargo.lock` is
432	    /// regenerated after the version bump. This prevents `cargo publish --locked`
433	    /// from failing with "lock file needs to be updated but --locked was passed".
434	    ///
435	    /// The result must appear in `ApplyOutcome::lockfile_refresh_results`.
436	    #[test]
437	    fn refresh_lockfiles_calls_cargo_update_workspace_when_cargo_bumped() {
438	        let dir = tempfile::tempdir().expect("create tempdir");
439	        let root = dir.path();
440	        std::fs::write(root.join("Cargo.lock"), "# stale lock").unwrap();
441	
442	        let calls = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
443	        let runner = RecordingRunner {
444	            calls: std::sync::Arc::clone(&calls),
445	        };
446	
447	        let plan = VersionPlan {
448	            bumps: vec![PlannedBump {
449	                package: PackageId::parse("cargo:my-crate").expect("valid package id"),
450	                from: cargo_version("1.0.0"),
451	                to: cargo_version("1.1.0"),
452	                severity: Severity::Minor,
453	                governed_by: None,
454	                reason: None,
455	                writes: vec![],
456	            }],
457	            ..Default::default()
458	        };
459	
460	        let permit = ApplyPermit::force_for_tests();
461	        let opts = ApplyOptions {
462	            refresh_lockfiles: true,
463	        };
464	        let outcome = apply_version_plan(root, &plan, &runner, &opts, &permit)
465	            .expect("apply_version_plan should succeed");
466	
467	        let recorded = calls.lock().unwrap().clone();
468	        let cargo_update_called = recorded
469	            .iter()
470	            .any(|(prog, args)| prog == "cargo" && args.iter().any(|a| a == "update"));
471	        assert!(
472	            cargo_update_called,
473	            "cargo update must be called when refresh_lockfiles=true and Cargo package is bumped; calls: {recorded:?}"
474	        );
475	
476	        let refresh_results = outcome
477	            .lockfile_refresh_results
478	            .expect("lockfile_refresh_results must be Some when refresh ran");
479	        assert!(
480	            refresh_results
481	                .iter()
482	                .any(|r| r.filename.as_os_str() == "Cargo.lock"),
483	            "Cargo.lock must appear in lockfile_refresh_results; got: {refresh_results:?}"
484	        );
485	    }
