271	/// Reads `package.json` at `abs_path` and returns `ManifestRole::Platform`
272	/// when the manifest declares both `os` and `cpu` constraint arrays (the napi
273	/// platform-package convention). Returns `ManifestRole::Canonical` for all
274	/// other npm packages and on any read/parse failure.
275	///
276	/// Note: this performs a second `fs::read` on each npm `package.json` because
277	/// the `manifest_cache` stores `Arc<dyn Manifest>` (which does not expose raw
278	/// JSON fields like `os`/`cpu`) rather than a raw `serde_json::Value`. Fixing
279	/// the redundancy would require a `Manifest::npm_role()` extension method in
280	/// the `callisto-manifests` crate.
281	fn detect_npm_role(abs_path: &Path) -> ManifestRole {
282	    let Ok(bytes) = std::fs::read(abs_path) else {
283	        return ManifestRole::Canonical;
284	    };
285	    let Ok(Value::Object(map)) = serde_json::from_slice(&bytes) else {
286	        return ManifestRole::Canonical;
287	    };
288	
289	    let has_os = map
290	        .get("os")
291	        .and_then(|v| v.as_array())
292	        .is_some_and(|a| !a.is_empty());
293	    let has_cpu = map
294	        .get("cpu")
295	        .and_then(|v| v.as_array())
296	        .is_some_and(|a| !a.is_empty());
297	
298	    if !has_os || !has_cpu {
299	        return ManifestRole::Canonical;
300	    }
301	
302	    let Some(platform) = map
303	        .get("os")
304	        .and_then(|v| v.as_array())
305	        .and_then(|a| a.first())
306	        .and_then(|v| v.as_str())
307	        .map(str::to_string)
308	    else {
309	        return ManifestRole::Canonical;
310	    };
311	
312	    let Some(arch) = map
313	        .get("cpu")
314	        .and_then(|v| v.as_array())
315	        .and_then(|a| a.first())
316	        .and_then(|v| v.as_str())
317	        .map(str::to_string)
318	    else {
319	        return ManifestRole::Canonical;
320	    };
321	
322	    ManifestRole::Platform {
323	        platform,
324	        arch,
325	        abi: None,
326	    }
327	}
