329	/// Explicit ecosystem precedence for primary-ID selection when a single
330	/// project directory contains manifests from multiple ecosystems (e.g., both
331	/// `Cargo.toml` and `package.json`). Lower value = higher priority.
332	///
333	/// Precedence: Cargo (0) > Npm (1) > Pypi (2) > others (255).
334	///
335	/// This function is used instead of `Ecosystem`'s derived `Ord` so that the
336	/// ordering is stable even if the `Ecosystem` variant sequence changes.
337	fn ecosystem_primary_priority(e: Ecosystem) -> u8 {
338	    match e {
339	        Ecosystem::Cargo => 0,
340	        Ecosystem::Npm => 1,
341	        Ecosystem::Pypi => 2,
342	        _ => u8::MAX,
343	    }
344	}
